
window.__CWSVGZ="";
(function(){
  "use strict";
  if(window.__cwSvgInit) return; window.__cwSvgInit=1;
  function ready(fn){ if(document.readyState!=="loading"){fn();} else {document.addEventListener("DOMContentLoaded",fn);} }
  var TS="plywood-supply-to-tiruppur";
  function keyFromPath(keys){
    var m=location.pathname.match(/\/blogs\/post\/(.+?)\/?$/);
    if(!m) return null;
    var slug;
    try{ slug=decodeURIComponent(m[1]).toLowerCase(); }catch(e){ slug=m[1].toLowerCase(); }
    if(slug===TS) return "tiruppur";
    var cand=slug.replace(/^plywood-supply-to-/, "");
    return (keys[cand] && ("plywood-supply-to-"+cand)===slug) ? cand : null;
  }
  function inflate(b64){
    try{
      if(typeof DecompressionStream==="undefined") return Promise.resolve(null);
      var bytes=Uint8Array.from(atob(b64),function(c){return c.charCodeAt(0);});
      return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
    }catch(e){ return Promise.resolve(null); }
  }
  function go(){
    try{
      if(location.pathname.indexOf("/blogs/post/")<0) return;
      var grid=document.querySelector(".theme-single-post .cwp__hero-grid")||document.querySelector(".cwp__hero-grid");
      if(!grid || grid.querySelector(".cwp__hero-art")) return;
      if(!window.__CWSVGZ) return;
      inflate(window.__CWSVGZ).then(function(json){
        try{
          if(!json) return;
          var b=JSON.parse(json);
          var key=keyFromPath(b);
          if(!key || !b[key]) return;
          if(grid.querySelector(".cwp__hero-art")) return;
          var art=document.createElement("div");
          art.className="cwp__hero-art"; art.setAttribute("aria-hidden","true");
          art.innerHTML=b[key];
          var txt=grid.querySelector(".cwp__hero-text");
          if(txt && txt.parentNode===grid){ grid.insertBefore(art, txt.nextSibling); }
          else { grid.appendChild(art); }
        }catch(e){}
      });
    }catch(e){}
  }
  ready(go);
})();
